"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { formatDate, operatorSourceUrl } from "../../../src/operator-ui/logic";
import { LEAD_CLASSIFICATIONS, classificationRequiresReason, describeDataQuality, enrichmentEligibility, isLikelyTicketingOrganisation, leadClassificationLabels } from "../../../src/incoming-leads/workspace";
import { describeSourceContext, type SourceContextEntry } from "../../../src/incoming-leads/source-context";

type Lead = Record<string, any>;
type Member = { user_id: string; member_role: string; active: boolean };
type WorkspaceData = { access: "VIEWER" | "OPERATOR" | "ADMIN"; leads: Lead[]; totalCount: number; metrics: Record<string, number>; members: Member[]; page: number; pageSize: number };

const sourceLabels: Record<string, string> = { DEMO_REQUEST: "Demo request", TALK_TO_SALES: "Talk to sales", TRIAL_STARTED: "Trial started", PRODUCT_ENQUIRY: "Product enquiry", RESOURCE_DOWNLOAD: "Resource download", TEMPLATE_DOWNLOAD: "Template download", NEWSLETTER_SIGNUP: "Newsletter signup", INTERNAL_TEST: "Internal / test" };
const stageLabels: Record<string, string> = { NEW: "New", REVIEWING: "Reviewing", QUALIFIED: "Qualified", CONTACTED: "Contacted", DEMO_SCHEDULED: "Demo scheduled", TRIAL_ACTIVE: "Trial active", PROPOSAL: "Proposal", NURTURE: "Nurture", CONVERTED: "Converted", DISQUALIFIED: "Disqualified", LOST: "Lost" };
const intentLabels: Record<string, string> = { VERY_HIGH: "Very high intent", HIGH: "High intent", MEDIUM: "High engagement", LOW: "Low intent", NURTURE: "Nurture", EXCLUDED: "Excluded" };
const enrichmentLabels: Record<string, string> = { NOT_ELIGIBLE: "Not eligible", BLOCKED_UNTIL_IDENTITY_RESOLVED: "Resolve identity first", EVIDENCE_AVAILABLE: "Evidence available", NOT_ENRICHED: "Not enriched" };
const views = [["needs-review", "Needs review"], ["active-leads", "Active leads"], ["high-intent", "High intent"], ["follow-up-due", "Follow-up due"], ["incomplete-data", "Incomplete data"], ["existing-customers", "Existing customers"], ["excluded", "Excluded"], ["all", "All records"]] as const;

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: string }) { return <span className={`operator-badge ${tone}`}>{children}</span>; }
function Loading() { return <div className="operator-empty"><span className="operator-kicker">PLEASE WAIT</span><p>Loading Incoming Leads…</p></div>; }
function Empty({ text = "No incoming leads match this view." }: { text?: string }) { return <div className="operator-empty"><span className="operator-kicker">NO RESULTS</span><h2>{text}</h2><p>Try another queue or adjust the filters. Source submissions are retained even when a record is excluded.</p></div>; }
function isOverdue(lead: Lead) { return Boolean(lead.follow_up_at && new Date(lead.follow_up_at).getTime() < Date.now() && !["CONVERTED", "DISQUALIFIED", "LOST"].includes(lead.stage)); }

function SourceContextDetails({ submission }: { submission: Lead }) {
  const context = describeSourceContext(submission);
  if (!context.downloadedTemplates.length && !context.downloadedResources.length && !context.isBookingRequest) return null;
  return <div className="incoming-source-context">
    {context.downloadedTemplates.length ? <div><b>Templates downloaded</b>{context.downloadedTemplates.map((item) => <span key={item}>{item}</span>)}</div> : null}
    {context.downloadedResources.length ? <div><b>Resource downloaded</b>{context.downloadedResources.map((item) => <span key={item}>{item}</span>)}</div> : null}
    {context.isBookingRequest ? <div><b>Booking request selections</b>{context.bookingSelections.length ? <dl>{context.bookingSelections.map((item: SourceContextEntry) => <div key={item.label}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl> : <span>Booking form selections were not recorded.</span>}</div> : null}
  </div>;
}

async function postIncoming(body: Record<string, unknown>) {
  const response = await fetch("/api/incoming-leads", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  const result = await response.json();
  if (!response.ok) throw new Error(result.message || "Incoming lead action failed.");
  return result;
}

function useIncomingData(query: string) {
  const [data, setData] = useState<WorkspaceData>({ access: "VIEWER", leads: [], totalCount: 0, metrics: {}, members: [], page: 1, pageSize: 25 });
  const [state, setState] = useState<"loading" | "ready" | "error">("loading");
  const refresh = useCallback(async (silent = false) => {
    if (!silent) setState("loading");
    try {
      const response = await fetch(`/api/incoming-leads?${query}`);
      if (!response.ok) throw new Error();
      setData(await response.json());
      setState("ready");
    } catch { setState("error"); }
  }, [query]);
  useEffect(() => { void refresh(); }, [refresh]);
  return { data, state, refresh };
}

function Header({ title, lede, action }: { title: string; lede: string; action?: React.ReactNode }) {
  return <header className="operator-page-header"><div><span className="operator-kicker">INBOUND TRIAGE</span><h1>{title}</h1><p>{lede}</p></div>{action}</header>;
}

function QualityLabels({ lead }: { lead: Lead }) {
  const quality = lead.data_quality_issues?.length ? lead.data_quality_issues : describeDataQuality(lead);
  return <div className="incoming-quality"><Badge tone={quality.length ? "review_required" : "qualified"}>{quality.length ? `${quality.length} data gap${quality.length === 1 ? "" : "s"}` : "Data complete"}</Badge><small>{quality.length ? quality[0] : enrichmentLabels[lead.enrichment_state] ?? "Ready for review"}</small></div>;
}

function QuickActions({ onOpen }: { lead?: Lead; readOnly?: boolean; onAction?: (action: string, value?: Record<string, unknown>, label?: string, undo?: boolean) => void; onOpen: () => void }) {
  // Triage choices such as Genuine, Exclude ticketing and Reviewed remain in the review drawer.
  return <button className="table-action incoming-review-action" type="button" onClick={(event) => { event.stopPropagation(); onOpen(); }}>Review</button>;
}

function LeadRow({ lead, selected, readOnly, active, onSelect, onOpen, onAction, onActivate }: { lead: Lead; selected: boolean; readOnly: boolean; active: boolean; onSelect: (checked: boolean) => void; onOpen: () => void; onAction: (action: string, value?: Record<string, unknown>, label?: string, undo?: boolean) => void; onActivate: () => void }) {
  const source = sourceLabels[lead.highest_intent_source_category] ?? lead.highest_intent_source_category;
  return <tr id={`lead-row-${lead.id}`} className={active ? "incoming-row-active" : undefined} tabIndex={0} onFocus={onActivate} onClick={onOpen}><td><input aria-label={`Select ${lead.display_name || lead.organisation_name || "incoming lead"}`} type="checkbox" checked={selected} onClick={(event) => event.stopPropagation()} onChange={(event) => onSelect(event.target.checked)} disabled={readOnly} /></td><td><strong>{lead.display_name || "Contact not yet identified"}</strong><span>{lead.organisation_name || "Organisation not yet resolved"}</span><small>{lead.contact_email || "No email retained"}</small><small>{lead.account_id ? "Existing account match" : "No confirmed account match"}</small></td><td><span>Original: {sourceLabels[lead.originating_source_category] ?? lead.originating_source_category}</span><small>Latest: {sourceLabels[lead.latest_source_category] ?? lead.latest_source_category}</small><small>{lead.activity_count} interaction{lead.activity_count === 1 ? "" : "s"} · highest {source}</small>{lead.activity_count > 1 ? <details className="incoming-inline-interactions" onClick={(event) => event.stopPropagation()}><summary>Interaction summary</summary><span>Original {sourceLabels[lead.originating_source_category] ?? lead.originating_source_category}; latest {sourceLabels[lead.latest_source_category] ?? lead.latest_source_category}. Open Quick review for the full retained timeline.</span></details> : null}</td><td><Badge tone={String(lead.current_intent).toLowerCase()}>{intentLabels[lead.current_intent] ?? lead.current_intent}</Badge><small>{lead.priority_reason}</small></td><td><Badge tone={String(lead.lead_classification).toLowerCase()}>{leadClassificationLabels[lead.lead_classification as keyof typeof leadClassificationLabels] ?? lead.lead_classification}</Badge><small>{stageLabels[lead.stage] ?? lead.stage}</small></td><td><span>{lead.owner_id ? String(lead.owner_id).slice(0, 8) : "Unassigned"}</span><small>{lead.follow_up_at ? `${isOverdue(lead) ? "Overdue" : "Due"} · ${formatDate(lead.follow_up_at)}` : lead.next_action || "No next action"}</small></td><td><span>{formatDate(lead.last_activity_at || lead.updated_at || lead.created_at)}</span><small>Last activity</small></td><td><QualityLabels lead={lead} /></td><td className="incoming-sticky-actions"><QuickActions lead={lead} readOnly={readOnly} onAction={onAction} onOpen={onOpen} /></td></tr>;
}

function BulkActions({ selectedIds, members, refresh, onComplete }: { selectedIds: string[]; members: Member[]; refresh: (silent?: boolean) => Promise<void>; onComplete: (count: number) => void }) {
  const [ownerId, setOwnerId] = useState("");
  const [classification, setClassification] = useState("NEEDS_REVIEW");
  const [reason, setReason] = useState("");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const run = async (bulkAction: string, value: Record<string, unknown>) => {
    if (!selectedIds.length || !window.confirm(`${bulkAction.replaceAll("_", " ")} ${selectedIds.length} selected record${selectedIds.length === 1 ? "" : "s"}?`)) return;
    setBusy(true); setMessage("");
    try { const result = await postIncoming({ action: "BULK", leadIds: selectedIds, bulkAction, value }); const count = Number(result.count ?? 0); setMessage(`${count} of ${selectedIds.length} selected records updated.`); onComplete(count); await refresh(true); } catch (error) { setMessage(`No records changed: ${error instanceof Error ? error.message : "Bulk update failed."}`); } finally { setBusy(false); }
  };
  if (!selectedIds.length) return null;
  return <section className="incoming-bulk-actions" aria-label="Bulk incoming lead actions"><strong>{selectedIds.length} selected on this page</strong><label>Assign owner<select value={ownerId} onChange={(event) => setOwnerId(event.target.value)}><option value="">Unassigned</option>{members.map((member) => <option key={member.user_id} value={member.user_id}>{member.user_id.slice(0, 8)} · {member.member_role}</option>)}</select></label><button className="operator-button secondary" disabled={busy} type="button" onClick={() => void run("ASSIGN_OWNER", { ownerId })}>Assign owner</button><button className="operator-button secondary" disabled={busy} type="button" onClick={() => void run("MARK_REVIEWED", {})}>Mark reviewed</button><label>Classification<select value={classification} onChange={(event) => setClassification(event.target.value)}>{LEAD_CLASSIFICATIONS.map((value) => <option key={value} value={value}>{leadClassificationLabels[value]}</option>)}</select></label><label>Reason{classificationRequiresReason(classification) ? " (required)" : ""}<input value={reason} onChange={(event) => setReason(event.target.value)} maxLength={1000} placeholder="Why this disposition applies" /></label><button className="operator-button" disabled={busy || (classificationRequiresReason(classification) && !reason.trim())} type="button" onClick={() => void run("CLASSIFY", { classification, reason })}>Classify selected</button>{message ? <span role="status">{message}</span> : null}</section>;
}

export function LegacyIncomingLeadsView() {
  const [view, setView] = useState("needs-review"); const [search, setSearch] = useState(""); const [source, setSource] = useState("ALL"); const [classification, setClassification] = useState("ALL"); const [intent, setIntent] = useState("ALL"); const [owner, setOwner] = useState("ALL"); const [stage, setStage] = useState("ALL"); const [followUpState, setFollowUpState] = useState("ALL"); const [dataQualityState, setDataQualityState] = useState("ALL"); const [enrichmentState, setEnrichmentState] = useState("ALL"); const [dateFrom, setDateFrom] = useState(""); const [dateTo, setDateTo] = useState(""); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(25); const [selected, setSelected] = useState<Set<string>>(new Set());
  const query = useMemo(() => new URLSearchParams({ view, search, source, classification, intent, owner, stage, followUpState, dataQualityState, enrichmentState, dateFrom, dateTo, page: String(page), pageSize: String(pageSize) }).toString(), [classification, dataQualityState, dateFrom, dateTo, enrichmentState, followUpState, intent, owner, page, pageSize, search, source, stage, view]);
  const { data, state, refresh } = useIncomingData(query);
  useEffect(() => setSelected(new Set()), [query]);
  if (state === "loading") return <Loading />; if (state === "error") return <Empty text="Incoming Leads data is unavailable." />;
  const readOnly = data.access === "VIEWER"; const totalPages = Math.max(1, Math.ceil(data.totalCount / pageSize)); const metrics = data.metrics;
  const selectAll = (checked: boolean) => setSelected(checked ? new Set(data.leads.map((lead) => lead.id)) : new Set());
  const setLeadSelected = (id: string, checked: boolean) => setSelected((current) => { const next = new Set(current); checked ? next.add(id) : next.delete(id); return next; });
  return <><Header title="What needs review?" lede="Classify each incoming record before enrichment or opportunity work. Interactions stay attached to one lead; excluded records remain auditable." action={readOnly ? <span className="incoming-read-only">Read-only viewer access</span> : undefined} />
    {readOnly ? <p className="incoming-read-only" role="status">Viewers can inspect source evidence and history but cannot change classification, ownership or follow-up.</p> : null}
    <section className="incoming-metrics" aria-label="Incoming lead operational metrics"><div><span>New / unreviewed</span><strong>{metrics.newUnreviewed ?? 0}</strong><small>Awaiting an operator review</small></div><div><span>Active genuine leads</span><strong>{metrics.activeGenuineLeads ?? 0}</strong><small>Excludes tests, internal and non-leads</small></div><div><span>High-intent leads</span><strong>{metrics.highIntentLeads ?? 0}</strong><small>High or very high demonstrated intent</small></div><div><span>Follow-ups due</span><strong>{metrics.followUpsDue ?? 0}</strong><small>Open operational follow-ups</small></div><div><span>Needs classification</span><strong>{metrics.needsClassification ?? 0}</strong><small>Not yet confirmed as a prospect or non-lead</small></div><div><span>Incomplete / needs enrichment</span><strong>{metrics.incompleteNeedsEnrichment ?? 0}</strong><small>Data gaps shown per record</small></div></section>
    <div className="incoming-view-tabs" role="tablist" aria-label="Incoming lead views">{views.map(([value, label]) => <button type="button" key={value} className={view === value ? "active" : undefined} onClick={() => { setView(value); setPage(1); }}>{label}</button>)}</div>
    <section className="incoming-filters"><label>Search<input value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Name, email, organisation or source" /></label><label>Source<select value={source} onChange={(event) => { setSource(event.target.value); setPage(1); }}><option value="ALL">All sources</option>{Object.entries(sourceLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Classification<select value={classification} onChange={(event) => { setClassification(event.target.value); setPage(1); }}><option value="ALL">All classifications</option>{LEAD_CLASSIFICATIONS.map((value) => <option key={value} value={value}>{leadClassificationLabels[value]}</option>)}</select></label><label>Intent<select value={intent} onChange={(event) => { setIntent(event.target.value); setPage(1); }}><option value="ALL">All intent</option>{Object.entries(intentLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Owner<select value={owner} onChange={(event) => { setOwner(event.target.value); setPage(1); }}><option value="ALL">All owners</option><option value="UNASSIGNED">Unassigned</option>{data.members.map((member) => <option key={member.user_id} value={member.user_id}>{member.user_id.slice(0, 8)} · {member.member_role}</option>)}</select></label><label>Stage<select value={stage} onChange={(event) => { setStage(event.target.value); setPage(1); }}><option value="ALL">All stages</option>{Object.entries(stageLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Follow-up<select value={followUpState} onChange={(event) => { setFollowUpState(event.target.value); setPage(1); }}><option value="ALL">Any follow-up</option><option value="DUE">Due now</option><option value="SCHEDULED">Scheduled</option><option value="NONE">None set</option></select></label><label>Data quality<select value={dataQualityState} onChange={(event) => { setDataQualityState(event.target.value); setPage(1); }}><option value="ALL">Any data state</option><option value="INCOMPLETE">Incomplete</option><option value="COMPLETE">Complete</option></select></label><label>Enrichment<select value={enrichmentState} onChange={(event) => { setEnrichmentState(event.target.value); setPage(1); }}><option value="ALL">Any enrichment state</option>{Object.entries(enrichmentLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>From date<input type="date" value={dateFrom} onChange={(event) => { setDateFrom(event.target.value); setPage(1); }} /></label><label>To date<input type="date" value={dateTo} onChange={(event) => { setDateTo(event.target.value); setPage(1); }} /></label></section>
    {!readOnly ? <BulkActions selectedIds={[...selected]} members={data.members} refresh={refresh} onComplete={() => setSelected(new Set())} /> : null}
    <section className="incoming-section"><div className="section-heading"><span className="operator-kicker">{views.find(([value]) => value === view)?.[1].toUpperCase()}</span><span className="muted">{data.totalCount} matching records · database-filtered</span></div>{data.leads.length ? <><div className="collection-table-wrap incoming-table"><table className="collection-table"><caption className="sr-only">Incoming leads</caption><thead><tr><th><input aria-label="Select all visible incoming leads" type="checkbox" checked={data.leads.length > 0 && data.leads.every((lead) => selected.has(lead.id))} onChange={(event) => selectAll(event.target.checked)} disabled={readOnly} /></th><th>CONTACT / ORGANISATION</th><th>SOURCE / INTERACTIONS</th><th>INTENT</th><th>CLASSIFICATION</th><th>OWNER / NEXT ACTION</th><th>LAST ACTIVITY</th><th>DATA / ENRICHMENT</th><th>ACTION</th></tr></thead><tbody>{data.leads.map((lead) => <LeadRow key={lead.id} lead={lead} selected={selected.has(lead.id)} readOnly={readOnly} active={false} onSelect={(checked) => setLeadSelected(lead.id, checked)} onOpen={() => undefined} onAction={() => undefined} onActivate={() => undefined} />)}</tbody></table></div><div className="pagination"><span>Showing {(page - 1) * pageSize + 1}–{Math.min(page * pageSize, data.totalCount)} of {data.totalCount}</span><label>Rows <select value={pageSize} onChange={(event) => { setPageSize(Number(event.target.value)); setPage(1); }}><option value="25">25</option><option value="50">50</option><option value="100">100</option></select></label><button type="button" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</button><span>Page {page} of {totalPages}</span><button type="button" disabled={page >= totalPages} onClick={() => setPage(page + 1)}>Next</button></div></> : <Empty />}</section>
  </>;
}

function QuickReviewDrawer({ leadId, readOnly, onClose, onAction }: { leadId: string; readOnly: boolean; onClose: () => void; onAction: (action: string, value?: Record<string, unknown>, label?: string, undo?: boolean) => Promise<void> }) {
  const [data, setData] = useState<Record<string, any>>({ submissions: [], activities: [], evidence: [], notes: [], changes: [], members: [] });
  const [state, setState] = useState<"loading" | "ready" | "error">("loading");
  const [classification, setClassification] = useState("NEEDS_REVIEW"); const [reason, setReason] = useState(""); const [blockReason, setBlockReason] = useState(""); const [nextAction, setNextAction] = useState(""); const [followUp, setFollowUp] = useState("");
  const refresh = useCallback(async () => { setState("loading"); try { const response = await fetch(`/api/incoming-leads?leadId=${encodeURIComponent(leadId)}`); if (!response.ok) throw new Error(); const result = await response.json(); setData(result); setClassification(result.lead?.lead_classification ?? "NEEDS_REVIEW"); setReason(result.lead?.classification_reason ?? ""); setBlockReason(result.lead?.classification_reason || (isLikelyTicketingOrganisation(result.lead?.organisation_name) ? "Organisation name indicates a likely ticketing company." : "")); setState("ready"); } catch { setState("error"); } }, [leadId]);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); }; window.addEventListener("keydown", close); return () => window.removeEventListener("keydown", close); }, [onClose]);
  if (state === "loading") return <aside className="incoming-drawer" aria-label="Quick review"><Loading /></aside>;
  if (state === "error" || !data.lead) return <aside className="incoming-drawer" aria-label="Quick review"><button type="button" onClick={onClose}>Close</button><Empty text="Quick review is unavailable." /></aside>;
  const lead = data.lead as Lead; const timeline = [...data.submissions.map((item: Lead) => ({ ...item, kind: "Source interaction", label: sourceLabels[item.source_category] ?? item.source_category, at: item.occurred_at })), ...data.activities.map((item: Lead) => ({ ...item, kind: "Activity", label: item.activity_type, at: item.occurred_at }))].sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime());
  const quality = describeDataQuality({ ...lead, account_website: data.account?.website, contact_role_title: data.contact?.role_title });
  const save = async (action: string, value: Record<string, unknown>, label?: string, undo?: boolean) => { await onAction(action, value, label, undo); await refresh(); };
return <aside className="incoming-drawer" aria-label={`Quick review for ${lead.display_name || lead.organisation_name || "incoming lead"}`}><header><div><span className="operator-kicker">QUICK REVIEW</span><h2>{lead.display_name || "Incoming contact"}</h2><p>{lead.organisation_name || "Organisation unresolved"} · {data.contact?.email || lead.contact_email || "No email retained"}</p></div><button type="button" aria-label="Close quick review" onClick={onClose}>×</button></header><div className="incoming-drawer-scroll"><section className="incoming-block-panel"><strong>Block as ticketing company</strong><p>{isLikelyTicketingOrganisation(lead.organisation_name) ? "The organisation name contains ‘ticket’; review this as a likely ticketing company." : "Use this when the organisation is a ticketing provider or other non-lead."}</p>{readOnly ? <p>Read-only viewer access.</p> : <><label>Reason<input value={blockReason} maxLength={1000} onChange={(event) => setBlockReason(event.target.value)} placeholder="Why this should be blocked" /></label><button className="operator-button incoming-block-button" disabled={!blockReason.trim()} type="button" onClick={() => void save("CLASSIFY", { classification: "TICKETING_PROVIDER", reason: blockReason }, "Blocked as ticketing company.", true)}>Block and save</button></>}</section><section><strong>Identity and commercial context</strong><p>{data.account?.name || "No confirmed account"} · {data.account?.website || "No domain recorded"}</p><p>{data.opportunity ? `Existing opportunity: ${data.opportunity.stage}` : "No incoming opportunity linked"} · {lead.activity_count} retained interactions</p></section><section><strong>Classification and exclusion</strong>{readOnly ? <p>Read-only viewer access.</p> : <><label>Classification<select value={classification} onChange={(event) => setClassification(event.target.value)}>{LEAD_CLASSIFICATIONS.map((value) => <option key={value} value={value}>{leadClassificationLabels[value]}</option>)}</select></label><label>Reason{classificationRequiresReason(classification) ? " (required)" : ""}<textarea value={reason} maxLength={1000} onChange={(event) => setReason(event.target.value)} /></label><button className="operator-button" disabled={classificationRequiresReason(classification) && !reason.trim()} type="button" onClick={() => void save("CLASSIFY", { classification, reason }, `Classified as ${leadClassificationLabels[classification as keyof typeof leadClassificationLabels]}.`, classification === "TICKETING_PROVIDER" || classification === "INTERNAL" || classification === "TEST_SYNTHETIC")}>Save classification</button><button className="operator-button secondary" type="button" onClick={() => void save("MARK_REVIEWED", {}, "Marked reviewed.")}>Mark reviewed</button></>}</section><section><strong>Owner and follow-up</strong><label>Owner<select disabled={readOnly} value={lead.owner_id || ""} onChange={(event) => void save("ASSIGN_OWNER", { ownerId: event.target.value }, "Owner updated.")}><option value="">Unassigned</option>{data.members.map((member: Member) => <option key={member.user_id} value={member.user_id}>{member.user_id.slice(0, 8)} · {member.member_role}</option>)}</select></label><label>Next action<input disabled={readOnly} value={nextAction || lead.next_action || ""} onChange={(event) => setNextAction(event.target.value)} /></label><button type="button" disabled={readOnly} onClick={() => void save("SET_NEXT_ACTION", { nextAction }, "Next action updated.")}>Save next action</button><label>Follow-up<input disabled={readOnly} type="datetime-local" value={followUp || (lead.follow_up_at ? new Date(lead.follow_up_at).toISOString().slice(0, 16) : "")} onChange={(event) => setFollowUp(event.target.value)} /></label><button type="button" disabled={readOnly} onClick={() => void save("SET_FOLLOW_UP", { followUpAt: followUp ? new Date(followUp).toISOString() : "" }, "Follow-up updated.")}>Save follow-up</button></section><section><strong>Data quality and enrichment</strong><div className="incoming-quality-list">{quality.map((item) => <Badge key={item} tone="review_required">{item}</Badge>)}</div><p>{enrichmentLabels[enrichmentEligibility({ ...lead, enrichment_evidence_count: data.evidence.length })]}. Viewing does not run enrichment.</p>{data.evidence.map((item: Lead) => <p className="incoming-note" key={item.id}>{item.claim}<small>{item.source_title || item.evidence_type}</small></p>)}</section><section><strong>Full source and activity timeline</strong><ol className="incoming-timeline">{timeline.map((item: Lead) => <li key={`${item.kind}-${item.id}`}><div><b>{item.label}</b><span>{item.kind} · {item.source_detail || item.summary || "Retained interaction"}</span>{item.kind === "Source interaction" ? <SourceContextDetails submission={item} /> : null}</div><time>{formatDate(item.at)}</time></li>)}</ol></section><details><summary>Notes and audit history</summary>{data.notes.map((item: Lead) => <p className="incoming-note" key={item.id}>{item.note}</p>)}{data.changes.map((item: Lead) => <p className="incoming-note" key={item.id}>{String(item.action).replaceAll("_", " ")} · {formatDate(item.created_at)}</p>)}</details><Link className="table-action" href={`/operator/incoming-leads/${lead.id}`}>Open full record ↗</Link></div></aside>;
}

export function IncomingLeadsView() {
   const [view, setView] = useState(() => typeof window === "undefined" ? "needs-review" : new URL(window.location.href).searchParams.get("view") ?? "needs-review"); const [search, setSearch] = useState(""); const [source, setSource] = useState("ALL"); const [classification, setClassification] = useState("ALL"); const [intent, setIntent] = useState("ALL"); const [owner, setOwner] = useState("ALL"); const [stage, setStage] = useState("ALL"); const [followUpState, setFollowUpState] = useState("ALL"); const [dataQualityState, setDataQualityState] = useState("ALL"); const [enrichmentState, setEnrichmentState] = useState("ALL"); const [dateFrom, setDateFrom] = useState(""); const [dateTo, setDateTo] = useState(""); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(25); const [selected, setSelected] = useState<Set<string>>(new Set()); const [activeId, setActiveId] = useState<string | null>(null); const [drawerId, setDrawerId] = useState<string | null>(null); const [toast, setToast] = useState<{ message: string; undoId?: string } | null>(null); const scrollY = useRef(0);
  const query = useMemo(() => new URLSearchParams({ view, search, source, classification, intent, owner, stage, followUpState, dataQualityState, enrichmentState, dateFrom, dateTo, page: String(page), pageSize: String(pageSize) }).toString(), [classification, dataQualityState, dateFrom, dateTo, enrichmentState, followUpState, intent, owner, page, pageSize, search, source, stage, view]);
  const { data, state, refresh } = useIncomingData(query);
  useEffect(() => setSelected(new Set()), [query]);
  const readOnly = data.access === "VIEWER"; const activeIndex = Math.max(0, data.leads.findIndex((lead) => lead.id === activeId));
  const focus = useCallback((id: string) => { setActiveId(id); requestAnimationFrame(() => document.getElementById(`lead-row-${id}`)?.focus()); }, []);
  const mutate = useCallback(async (leadId: string, action: string, value: Record<string, unknown> = {}, label = "Incoming lead updated.", undo = false) => { try { scrollY.current = window.scrollY; const currentIndex = data.leads.findIndex((lead) => lead.id === leadId); const nextVisible = data.leads[currentIndex + 1] ?? data.leads[currentIndex - 1]; await postIncoming({ action, leadId, value }); setSelected((current) => { const next = new Set(current); next.delete(leadId); return next; }); setToast({ message: label, undoId: undo ? leadId : undefined }); await refresh(true); if (action === "CLASSIFY") setDrawerId(null); if (nextVisible) focus(nextVisible.id); requestAnimationFrame(() => window.scrollTo({ top: scrollY.current })); } catch (error) { setToast({ message: error instanceof Error ? error.message : "The row was not changed." }); } }, [data.leads, focus, refresh]);
  useEffect(() => { const onKey = (event: KeyboardEvent) => { const target = event.target as HTMLElement | null; if (target?.matches("input, textarea, select, [contenteditable=true]")) return; if (event.key === "Escape") { setDrawerId(null); return; } const lead = data.leads[activeIndex]; if (!lead) return; if (event.key === "j" || event.key === "ArrowDown") { event.preventDefault(); const next = data.leads[Math.min(activeIndex + 1, data.leads.length - 1)]; if (next) focus(next.id); } if (event.key === "k" || event.key === "ArrowUp") { event.preventDefault(); const previous = data.leads[Math.max(activeIndex - 1, 0)]; if (previous) focus(previous.id); } if (event.key === "Enter") { event.preventDefault(); setDrawerId((current) => current ? null : lead.id); } if (!readOnly && event.key.toLowerCase() === "g") void mutate(lead.id, "CLASSIFY", { classification: "GENUINE_PROSPECT", reason: "Operator keyboard triage: genuine prospect." }, "Marked as a genuine prospect."); if (!readOnly && event.key.toLowerCase() === "r") void mutate(lead.id, "MARK_REVIEWED", {}, "Marked reviewed."); if (!readOnly && ["x", "e"].includes(event.key.toLowerCase())) setDrawerId(lead.id); }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, [activeIndex, data.leads, focus, mutate, readOnly]);
  if (state === "loading") return <Loading />; if (state === "error") return <Empty text="Incoming Leads data is unavailable." />;
  const selectAll = (checked: boolean) => setSelected(checked ? new Set(data.leads.map((lead) => lead.id)) : new Set()); const setLeadSelected = (id: string, checked: boolean) => setSelected((current) => { const next = new Set(current); checked ? next.add(id) : next.delete(id); return next; }); const totalPages = Math.max(1, Math.ceil(data.totalCount / pageSize));
   return <><Header title="Incoming leads" lede="Work the strongest commercial signals first, with source history always visible." action={<details className="incoming-shortcuts"><summary>Keyboard shortcuts</summary><p>J/K or ↑/↓ move · Enter opens review · G genuine · X/E exclusion choices · R reviewed · Esc closes.</p></details>} />{readOnly ? <p className="incoming-read-only" role="status">Viewers can inspect evidence and history but cannot change classification, ownership or follow-up.</p> : null}<section className="incoming-metrics" aria-label="Incoming lead operational metrics"><div><span>Needs review</span><strong>{data.metrics.newUnreviewed ?? 0}</strong><small>human triage</small></div><div><span>High intent</span><strong>{data.metrics.highIntentLeads ?? 0}</strong><small>demo / talk to sales</small></div><div><span>Follow-up due</span><strong>{data.metrics.followUpsDue ?? 0}</strong><small>nothing overdue</small></div><div><span>Active genuine</span><strong>{data.metrics.activeGenuineLeads ?? 0}</strong><small>current observed state</small></div></section><div className="incoming-view-tabs incoming-sticky-header" role="tablist" aria-label="Incoming lead views">{views.filter((entry, index) => index < 4 || index === 7).map(([value, label], index) => { const count = index === 0 ? data.metrics.newUnreviewed : index === 1 ? data.metrics.activeGenuineLeads : index === 2 ? data.metrics.highIntentLeads : index === 3 ? data.metrics.followUpsDue : data.metrics.sourceActivities ?? data.totalCount; return <button type="button" key={value} className={view === value ? "active" : undefined} onClick={() => { setView(value); setPage(1); }}>{label} {count ?? 0}</button>; })}</div><section className="incoming-filters"><label className="incoming-search-filter">Search<input value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Search contact, organisation or source…" /></label><details className="incoming-advanced-filters"><summary>More filters</summary><div className="incoming-advanced-filter-grid"><label>Classification<select value={classification} onChange={(event) => { setClassification(event.target.value); setPage(1); }}><option value="ALL">All classifications</option>{LEAD_CLASSIFICATIONS.map((value) => <option key={value} value={value}>{leadClassificationLabels[value]}</option>)}</select></label><label>Intent<select value={intent} onChange={(event) => { setIntent(event.target.value); setPage(1); }}><option value="ALL">All intent</option>{Object.entries(intentLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Owner<select value={owner} onChange={(event) => { setOwner(event.target.value); setPage(1); }}><option value="ALL">All owners</option><option value="UNASSIGNED">Unassigned</option>{data.members.map((member) => <option key={member.user_id} value={member.user_id}>{member.user_id.slice(0, 8)} · {member.member_role}</option>)}</select></label><label>Follow-up<select value={followUpState} onChange={(event) => { setFollowUpState(event.target.value); setPage(1); }}><option value="ALL">Any follow-up</option><option value="DUE">Due now</option><option value="SCHEDULED">Scheduled</option><option value="NONE">None set</option></select></label></div></details></section>{!readOnly ? <BulkActions selectedIds={[...selected]} members={data.members} refresh={refresh} onComplete={() => { setSelected(new Set()); setToast({ message: `${selected.size} selected records updated.` }); }} /> : null}<section className="incoming-section"><div className="section-heading"><span className="operator-kicker">{views.find(([value]) => value === view)?.[1].toUpperCase()}</span><span className="muted">{data.totalCount} records · source history retained</span></div>{data.leads.length ? <><div className="collection-table-wrap incoming-table"><table className="collection-table"><caption className="sr-only">Incoming leads</caption><thead><tr><th><input aria-label="Select all visible incoming leads" type="checkbox" checked={data.leads.length > 0 && data.leads.every((lead) => selected.has(lead.id))} onChange={(event) => selectAll(event.target.checked)} disabled={readOnly} /></th><th>CONTACT / ACCOUNT</th><th>WHY THIS EXISTS</th><th>INTENT</th><th>CLASSIFICATION / STAGE</th><th>OWNER / FOLLOW-UP</th><th>DATA QUALITY</th><th>ACTION</th></tr></thead><tbody>{data.leads.map((lead) => <LeadRow key={lead.id} lead={lead} selected={selected.has(lead.id)} readOnly={readOnly} active={lead.id === activeId} onSelect={(checked) => setLeadSelected(lead.id, checked)} onOpen={() => { scrollY.current = window.scrollY; setActiveId(lead.id); setDrawerId(lead.id); }} onAction={(action, value, label, undo) => void mutate(lead.id, action, value, label, undo)} onActivate={() => setActiveId(lead.id)} />)}</tbody></table></div><div className="incoming-mobile-cards">{data.leads.map((lead) => <article key={lead.id} className="incoming-lead-card"><strong>{lead.display_name || "Incoming contact"}</strong><span>{lead.organisation_name || "Organisation unresolved"} · {lead.contact_email || "No email"}</span><p>{sourceLabels[lead.latest_source_category] ?? lead.latest_source_category} · {lead.activity_count} interactions · {intentLabels[lead.current_intent] ?? lead.current_intent}</p><QuickActions lead={lead} readOnly={readOnly} onAction={(action, value, label, undo) => void mutate(lead.id, action, value, label, undo)} onOpen={() => setDrawerId(lead.id)} /></article>)}</div><div className="pagination"><span>Showing {(page - 1) * pageSize + 1}–{Math.min(page * pageSize, data.totalCount)} of {data.totalCount}</span><button type="button" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</button><span>Page {page} of {totalPages}</span><button type="button" disabled={page >= totalPages} onClick={() => setPage(page + 1)}>Next</button></div></> : <Empty />}</section>{drawerId ? <QuickReviewDrawer leadId={drawerId} readOnly={readOnly} onClose={() => { setDrawerId(null); requestAnimationFrame(() => window.scrollTo({ top: scrollY.current })); }} onAction={(action, value, label, undo) => mutate(drawerId, action, value, label, undo)} /> : null}{toast ? <div className="incoming-toast" role="status">{toast.message}{toast.undoId ? <button type="button" onClick={() => void mutate(toast.undoId!, "RESTORE", {}, "Exclusion undone.")}>Undo exclusion</button> : null}<button type="button" aria-label="Dismiss confirmation" onClick={() => setToast(null)}>×</button></div> : null}</>;
}

function DetailAction({ label, action, leadId, value = {}, disabled, onDone }: { label: string; action: string; leadId: string; value?: Record<string, unknown>; disabled?: boolean; onDone: () => Promise<void> }) {
  const [busy, setBusy] = useState(false); const [message, setMessage] = useState("");
  return <><button className="operator-button secondary" type="button" disabled={busy || disabled} onClick={() => { if (!window.confirm(`${label}?`)) return; setBusy(true); void postIncoming({ action, leadId, value }).then(async (result) => { setMessage(result.message); await onDone(); }).catch((error) => setMessage(error instanceof Error ? error.message : "Action failed.")).finally(() => setBusy(false)); }}>{busy ? "Saving…" : label}</button>{message ? <small role="status">{message}</small> : null}</>;
}

export function IncomingLeadDetailView({ leadId }: { leadId: string }) {
  const [data, setData] = useState<Record<string, any>>({ changes: [], notes: [], submissions: [], activities: [], members: [], evidence: [] }); const [state, setState] = useState<"loading" | "ready" | "error">("loading"); const [note, setNote] = useState(""); const [nextAction, setNextAction] = useState(""); const [followUp, setFollowUp] = useState(""); const [classification, setClassification] = useState(""); const [reason, setReason] = useState(""); const [message, setMessage] = useState("");
  const refresh = useCallback(async () => { setState("loading"); try { const response = await fetch(`/api/incoming-leads?leadId=${encodeURIComponent(leadId)}`); if (!response.ok) throw new Error(); setData(await response.json()); setState("ready"); } catch { setState("error"); } }, [leadId]);
  useEffect(() => { void refresh(); }, [refresh]);
  const save = async (action: string, value: Record<string, unknown>) => { const result = await postIncoming({ action, leadId, value }); setMessage(result.message); await refresh(); };
  if (state === "loading") return <Loading />; if (state === "error" || !data.lead) return <Empty text="Incoming lead detail is unavailable." />;
  const lead = data.lead as Lead; const policy = lead.communication_policy ?? {}; const readOnly = data.access === "VIEWER"; const selectedClassification = classification || lead.lead_classification || "NEEDS_REVIEW"; const quality = describeDataQuality({ ...lead, account_website: data.account?.website, contact_role_title: data.contact?.role_title }); const enrichment = enrichmentEligibility({ ...lead, enrichment_evidence_count: data.evidence?.length }); const timeline: Lead[] = [...data.submissions.map((item: Lead) => ({ ...item, timelineType: "Source interaction", time: item.occurred_at, label: sourceLabels[item.source_category] ?? item.source_category })), ...data.activities.map((item: Lead) => ({ ...item, timelineType: "Activity", time: item.occurred_at, label: item.activity_type }))].sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());
  const excluded = enrichment === "NOT_ELIGIBLE";
  return <><Header title={lead.display_name || "Incoming contact"} lede={`${lead.organisation_name || "Organisation not yet resolved"} · ${lead.product_code === "event-suite" ? "Event Suite" : lead.product_code}`} action={<Link className="operator-button secondary" href="/operator/incoming-leads">Back to Incoming Leads</Link>} />
    {readOnly ? <p className="incoming-read-only">Read-only viewer access. Classification and operational controls are unavailable.</p> : null}
    <div className="incoming-detail-grid"><main><section className="incoming-detail-card incoming-summary"><div><span className="operator-label">ORIGINAL ACQUISITION</span><strong>{sourceLabels[lead.originating_source_category] ?? lead.originating_source_category}</strong><p>{lead.originating_source_detail || "Source detail not recorded"}</p></div><div><span className="operator-label">LATEST INTERACTION</span><strong>{sourceLabels[lead.latest_source_category] ?? lead.latest_source_category}</strong><p>{lead.latest_source_detail || "Source detail not recorded"}</p></div><div><span className="operator-label">HIGHEST DEMONSTRATED INTENT</span><strong>{intentLabels[lead.current_intent] ?? lead.current_intent}</strong><p>{lead.activity_count} interactions · {lead.priority_reason}</p></div></section>
      <section className="incoming-detail-card"><span className="operator-kicker">IDENTITY, ACCOUNT AND LIFECYCLE</span><div className="incoming-detail-facts"><div><b>Classification</b><span>{leadClassificationLabels[lead.lead_classification as keyof typeof leadClassificationLabels] ?? "Needs review"}</span></div><div><b>Lifecycle stage</b><span>{stageLabels[lead.stage] ?? lead.stage}</span></div><div><b>Contact</b><span>{data.contact?.email || "No contact email retained"}</span></div><div><b>Organisation/account</b><span>{data.account?.name || "No confirmed account match"}</span></div><div><b>Website/domain</b><span>{data.account?.website || "Not recorded"}</span></div><div><b>Opportunity / tenant relationship</b><span>{data.opportunity ? `${data.opportunity.stage}${data.opportunity.conversion_route ? ` · ${data.opportunity.conversion_route}` : ""}` : "No incoming opportunity linked"}</span></div></div></section>
      <section className="incoming-detail-card"><span className="operator-kicker">DATA QUALITY AND ENRICHMENT</span><div className="incoming-quality-list">{quality.length ? quality.map((item) => <Badge key={item} tone="review_required">{item}</Badge>) : <Badge tone="qualified">No identified data gaps</Badge>}</div><p>{enrichmentLabels[enrichment] ?? enrichment}. Viewing this record never triggers enrichment.</p>{data.evidence.length ? <div className="incoming-evidence-list">{data.evidence.map((item: Lead) => { const sourceUrl = operatorSourceUrl(item.source_url); return <article key={item.id}><strong>{item.claim}</strong><span>{item.evidence_type} · confidence {item.confidence ?? "not scored"} · {formatDate(item.observed_at || item.created_at)}</span>{sourceUrl ? <a href={sourceUrl} target="_blank" rel="noreferrer">Open source ↗</a> : null}</article>; })}</div> : <p>No research evidence is attached to this account.</p>}</section>
      <section className="incoming-detail-card"><span className="operator-kicker">COMPLETE INTERACTION TIMELINE</span><ol className="incoming-timeline">{timeline.map((item) => <li key={`${item.timelineType}-${item.id}`}><div><strong>{item.label}</strong><span>{item.timelineType} · {item.source_detail || item.summary || "Interaction retained"}</span></div><time>{formatDate(item.time)}</time></li>)}</ol></section>
      <section className="incoming-detail-card"><span className="operator-kicker">SOURCE AND ATTRIBUTION RECORDS</span>{data.submissions.map((submission: Lead) => <details className="incoming-source-record" key={submission.id}><summary>{submission.source_system} · {submission.source_record_id} · {submission.processing_state}</summary><p>{submission.source_page || "Page not recorded"} · {submission.resource_identifier || submission.template_identifier || "No resource/template"} · {submission.campaign_identifier || "No campaign"} · consent {submission.consent_state} · received {formatDate(submission.received_at)}</p><SourceContextDetails submission={submission} /></details>)}</section>
    </main><aside className="incoming-side-panel"><section className="incoming-detail-card"><span className="operator-kicker">PRIMARY OPERATOR ACTIONS</span>{readOnly ? <p>Operational controls require operator or admin access.</p> : <><label>Classification<select value={selectedClassification} onChange={(event) => setClassification(event.target.value)}>{LEAD_CLASSIFICATIONS.map((value) => <option key={value} value={value}>{leadClassificationLabels[value]}</option>)}</select></label><label>Classification reason{classificationRequiresReason(selectedClassification) ? " (required)" : ""}<textarea value={reason} onChange={(event) => setReason(event.target.value)} maxLength={1000} placeholder="Why this is a prospect, customer or non-lead" /></label><button className="operator-button" type="button" disabled={classificationRequiresReason(selectedClassification) && !reason.trim()} onClick={() => void save("CLASSIFY", { classification: selectedClassification, reason }).catch((error) => setMessage(error.message))}>Save classification</button>{lead.lead_classification !== "NEEDS_REVIEW" ? <DetailAction label="Restore to needs review" action="RESTORE" leadId={lead.id} onDone={refresh} /> : null}</>}</section>
      <section className="incoming-detail-card"><span className="operator-kicker">OWNERSHIP AND FOLLOW-UP</span><label>Stage<select disabled={readOnly || excluded} value={lead.stage} onChange={(event) => void save("CHANGE_STAGE", { stage: event.target.value }).catch((error) => setMessage(error.message))}>{Object.entries(stageLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label><label>Owner<select disabled={readOnly} value={lead.owner_id || ""} onChange={(event) => void save("ASSIGN_OWNER", { ownerId: event.target.value }).catch((error) => setMessage(error.message))}><option value="">Unassigned</option>{data.members.map((member: Member) => <option key={member.user_id} value={member.user_id}>{member.user_id.slice(0, 8)} · {member.member_role}</option>)}</select></label><label>Next action<input disabled={readOnly} value={nextAction || lead.next_action || ""} onChange={(event) => setNextAction(event.target.value)} /></label><button className="operator-button" type="button" disabled={readOnly} onClick={() => void save("SET_NEXT_ACTION", { nextAction }).catch((error) => setMessage(error.message))}>Save next action</button><label>Follow-up date<input disabled={readOnly} type="datetime-local" value={followUp || (lead.follow_up_at ? new Date(lead.follow_up_at).toISOString().slice(0, 16) : "")} onChange={(event) => setFollowUp(event.target.value)} /></label><button className="operator-button" type="button" disabled={readOnly} onClick={() => void save("SET_FOLLOW_UP", { followUpAt: followUp ? new Date(followUp).toISOString() : "" }).catch((error) => setMessage(error.message))}>Save follow-up</button>{message ? <p className="incoming-status" role="status">{message}</p> : null}{!readOnly ? <div className="incoming-action-grid"><DetailAction label="Mark reviewed" action="MARK_REVIEWED" leadId={lead.id} onDone={refresh} /><DetailAction label="Mark contacted" action="MARK_CONTACTED" leadId={lead.id} disabled={excluded} onDone={refresh} /><DetailAction label="Qualify" action="QUALIFY" leadId={lead.id} disabled={excluded} onDone={refresh} /><DetailAction label="Move to nurture" action="MOVE_TO_NURTURE" leadId={lead.id} disabled={excluded} onDone={refresh} /></div> : null}</section>
      <section className="incoming-detail-card"><span className="operator-kicker">COMMUNICATION TREATMENT</span><h2>{policy.permittedTreatment || "Policy not recorded"}</h2><p className="incoming-no-send">No send, schedule, provider or message action exists in this workspace. Excluded records are never enrichment-eligible.</p></section>
      <section className="incoming-detail-card"><span className="operator-kicker">NOTES AND AUDIT HISTORY</span>{!readOnly ? <><textarea value={note} onChange={(event) => setNote(event.target.value)} maxLength={2000} placeholder="Record a human decision or context" /><button className="operator-button" type="button" disabled={!note.trim()} onClick={() => void save("ADD_NOTE", { note }).then(() => setNote("")).catch((error) => setMessage(error.message))}>Add note</button></> : null}{data.notes.map((item: Lead) => <p className="incoming-note" key={item.id}>{item.note}<small>{formatDate(item.created_at)}</small></p>)}<details><summary>Classification and change history</summary>{data.changes.map((change: Lead) => <p className="incoming-note" key={change.id}>{String(change.action).replaceAll("_", " ")} · {formatDate(change.created_at)}</p>)}</details></section>
    </aside></div></>;
}
